bg = 9

# Check ALL columns for non-bg content
print("Scanning all 22 columns...")
has_fg_counts = {}
all_bg_counts = {0: 0}

for c in range(22):
    col_pat = tuple(inp[r][c] for r in range(14))
    is_all_bg = all(v == bg for v in col_pat)

    if is_all_bg:
        all_bg_counts[c] = 1  # marker
        print(f"Col {c}: ALL BACKGROUND")
    else:
        has_fg_counts[c] = 1
        first_fg_row = next((i for i,v in enumerate(col_pat) if v != bg), -1)
        print(f"Col {c}: has FG at row {first_fg_row}, pattern starts with {list(col_pat)[:3]}")

print(f"\nColumns with FG: {len(has_fg_counts)}, Columns all-bg: {sum(all_bg_counts.values())}")
